 dict(n=11, area='Tu compromiso', t1='Elegir las acciones', t2='que te aplican', idx='Elegir las acciones que te aplican', idx_corto='Elegir acciones',
  idxp='Hay muchas ideas. Lo difícil es elegir las pocas que cambian algo.',
  gancho='Has visto muchas ideas y no todas te aplican. Lo difícil es elegir las pocas que cambian algo en tu equipo.',
  noT='Una lista larga de buenas intenciones que no se llega a cumplir.',
  siT='Dos o tres acciones elegidas según los perfiles que tienes de verdad, con una persona concreta y un plazo.',
  caso='Un responsable llega con doce ideas apuntadas. Las aplica todas a la vez a todo el equipo y a las dos semanas no recuerda ninguna. Otro elige dos, las prueba con una persona y comprueba si funcionan. El segundo es el que acaba cambiando algo.',
  clab='¿Qué haces tú?', clead='Elige la mejor respuesta en cada situación.', rl=AB,
  items=[I('«Tienes muchas ideas de acciones.»', 'A: Aplicar todas.  B: Elegir dos o tres según los perfiles de tu equipo.', 1, 'B: pocas acciones bien elegidas se cumplen.'),
         I('«Una acción te gusta mucho, pero depende de tu responsable.»', 'A: Esperar a que lo decida.  B: Plantearla con una petición concreta y empezar por lo que sí depende de ti.', 1, 'B: no te quedas parado y sigues avanzando.'),
         I('«Tienes varios perfiles distintos en el equipo.»', 'A: Empezar por una persona.  B: Cambiar el plan de todo el equipo de golpe.', 0, 'A: una persona primero te permite comprobar qué funciona.'),
         I('«Quieres saber si lo que haces funciona.»', 'A: Decidir antes qué verás o escucharás si funciona.  B: Esperar a ver los números del mes.', 0, 'A: un indicador que puedes observar antes te da una respuesta más rápida.')],
  extra='Cuatro preguntas para elegir: ¿a quién tengo?, ¿qué pesa más (flexibilidad, ambiente o salario)?, ¿qué depende de mí? y ¿cómo sabré si funciona?',
  error='Tomar todas las ideas porque «todas son buenas». Si no puedes hacerlas, no cambian nada.',
  plead='Responde con una frase cada vez.',
  q=[('¿Qué dos acciones de las que has visto elegirías?', 'Las más aplicables a tu equipo.', 'Pedir la disponibilidad con antelación y presentar a un recién llegado a un compañero afín.'),
     ('¿Qué verás o escucharás si funcionan?', 'Algo que puedas observar.', 'Que pida menos cambios de última hora y que coma con alguien del equipo.')],
  acc='Escribe tus dos acciones y la persona con la que empezarás cada una.', chk='Ya las escribí',
  rev='¿Siguen siendo las dos más importantes? Cámbialas si ves otra más urgente.',
  frase='Pocas acciones, con una persona y una fecha.'),

